BEGIN;
INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('linux-q125', 'ブートプロセスの流れ',
   'パソコンの電源ボタンを押した瞬間、OS(Linuxカーネル)よりも先に動き始めるものはどれか。',
   NULL::text,
   '["BIOS/UEFI（マザーボードに組み込まれた最初のプログラム）", "Linuxカーネル本体（ハードウェアと橋渡しするOSの中心部分）", "ログイン画面を出すシェル（コマンドを受け付ける対話用プログラム）", "systemd（サービスの起動や監視をまとめて担当する仕組み）"]',
   0, '[0]', 'single',
   '{"asked": "電源投入直後、OSより先に動くものを選ぶ問題。", "point": "電源が入って一番最初に動くのは、OSではなくマザーボードに焼き込まれたBIOS/UEFIというプログラム。", "kid": "OS(Linux)はハードディスクやSSDの中に入っているただのデータのかたまり。電源を入れた直後はまだ何も読み込まれていないので、OSを起動する係が別に要る。その係がBIOS/UEFIで、マザーボードにあらかじめ焼き込まれている。", "eg": "たとえるなら、OSは「会場に届いた台本」。BIOS/UEFIは「会場の電気をつけて、台本を運んでくる進行係」。進行係が動かないと、台本(OS)がどんなに立派でも誰も読み始められない。", "terms": [["BIOS/UEFI", "マザーボードに組み込まれた、電源投入直後に動く最初のプログラム。ハードウェアの点検とOSの呼び出しを担当する"], ["カーネル", "OSの中心部分。ハードウェアとプログラムの橋渡しをする"]], "why_asked": "「OSが勝手に立ち上がる」と思っていると、電源を入れてから画面が映るまでの間に何が起きているかが空白のままになる。ここを埋めておくと、起動しないトラブルの切り分けがしやすくなる。", "think": "電源を入れた直後、メモリの中には何のプログラムも読み込まれていない。何かが最初に動いて「次にOSを読み込む」という手順を実行しないと、OSは永遠に始まらない。その最初の一歩を担当するのがBIOS/UEFIで、ハードウェアが壊れていないか簡単に点検してから、次の工程（ブートローダの呼び出し）に進む。", "vs": "「OSが自動的に起動する」という感覚とは違い、実際には「起動させる係」が別に存在する、という順番の理解がここでの決め手。", "usecase": "パソコンの電源を入れてもロゴすら出ないような故障のとき、「BIOS/UEFIより手前(電源・マザーボード)の問題か、それより後ろ(OS)の問題か」を切り分ける手がかりになる。", "opt": ["正解。マザーボードに組み込まれ、電源投入直後に真っ先に動く。", "Linuxカーネルはストレージの中にあるデータであり、まだ読み込まれる前なので電源投入直後にはまだ動けない。", "ログイン画面を出すシェルは、OSがかなり起動が進んだ後半の工程で表示されるもので、最初に動くものではない。", "systemdはOS起動の後半でサービスを管理する仕組みであり、電源投入直後にはまだ登場しない。"], "viz": "<svg viewBox=\"0 0 340 160\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"60\" y=\"20\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"35\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">電源ON</text><line x1=\"170\" y1=\"42\" x2=\"170\" y2=\"46\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"46\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.4\"/><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">BIOS/UEFI</text><line x1=\"170\" y1=\"68\" x2=\"170\" y2=\"72\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"72\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"87\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">ブートローダ</text><line x1=\"170\" y1=\"94\" x2=\"170\" y2=\"98\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"98\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"113\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">カーネル</text><line x1=\"170\" y1=\"120\" x2=\"170\" y2=\"124\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"124\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"139\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">ログイン画面</text></svg>"}'),

  ('linux-q126', 'ブートプロセスの流れ',
   'BIOS/UEFIが担当する役割として最も適切なものはどれか。',
   NULL::text,
   '["ハードウェアの簡易点検をしてから、OSを読み込む係（ブートローダ）を呼び出す", "デスクトップ環境が起動した後、アプリケーションのウィンドウを画面に表示する", "OSが起動した後、ネットワーク越しにファイルを他のパソコンへ送る", "ログインの仕組みが、入力されたパスワードを暗号化して保存する"]',
   0, '[0]', 'single',
   '{"asked": "BIOS/UEFIが具体的に何をしているかを選ぶ問題。", "point": "BIOS/UEFIの仕事は「壊れていないか軽くチェックしてから、次の係(ブートローダ)にバトンを渡す」こと。", "kid": "電源を入れた直後、BIOS/UEFIはまずメモリやディスクなどの部品がちゃんとつながっているかを簡単にチェックする。問題がなければ、ディスクの中から「OSを起動する係(ブートローダ)」を探し出して、そこに処理を引き渡す。", "eg": "たとえるなら、BIOS/UEFIは「会場に入る前の受付」。マイクや照明が壊れていないかざっと確認してから、「では次はブートローダさん、お願いします」とバトンを渡す進行役。", "terms": [["ブートローダ", "BIOS/UEFIから処理を引き継ぎ、カーネルをメモリに読み込んで起動する係"]], "why_asked": "BIOS/UEFIを「OSそのもの」だと誤解していると、起動時のどの段階でトラブルが起きているか判断できなくなる。", "think": "OSはまだディスクの中に眠っているだけの状態からスタートする。BIOS/UEFIの役目は「OSを直接動かす」ことではなく、「部品の点検」と「次の係への引き継ぎ」の2つに限られている。この役割分担があるおかげで、ハードウェアの違い(メーカーの違い)をBIOS/UEFIの層で吸収でき、OS側は起動の細かい手順を気にしなくてよくなる。", "vs": "ブートローダと役割が混同されやすいが、BIOS/UEFIは「点検して引き渡すだけ」、ブートローダは「実際にカーネルをメモリへ運んで起動する」という、担当がはっきり分かれている。", "usecase": "起動時に「ビープ音が鳴って何も映らない」ようなハードウェア異常は、この段階(BIOS/UEFI)で止まっているサインとして扱われる。", "opt": ["正解。ハードウェアの簡易点検をして、次の係(ブートローダ)を呼び出すのがBIOS/UEFIの役割。", "アプリケーションのウィンドウ表示は、OSがかなり起動し終わった後、デスクトップ環境などが担当する仕事。", "ネットワーク越しのファイル転送は、OS上で動くアプリケーションの仕事であり、BIOS/UEFIの役割ではない。", "パスワードの暗号化保存は、OS側のログインの仕組みが担当する仕事で、BIOS/UEFIの段階ではまだ扱われない。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"18\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"62\" y=\"51\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">電源ON</text><line x1=\"108\" y1=\"52\" x2=\"121\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"125\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">BIOS/UEFI</text><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">点検</text><line x1=\"215\" y1=\"52\" x2=\"228\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"232\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"278\" y=\"51\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">ブートローダへ</text></svg>"}'),

  ('linux-q127', 'ブートプロセスの流れ',
   'ブートローダの役割として最も適切なものはどれか。',
   NULL::text,
   '["ディスクの中にあるLinuxカーネルをメモリに読み込み、実行を開始させる", "OSが起動した後、ネットワークの設定ファイルを編集する作業を行う", "シェルが、ユーザーの打ったコマンドを解釈して実行する", "ファイルシステムの仕組みが、権限(rwx)を計算して表示する"]',
   0, '[0]', 'single',
   '{"asked": "ブートローダが具体的に何をしているかを選ぶ問題。", "point": "ブートローダの仕事は「ディスクの中で眠っているカーネルを見つけ出し、メモリに運んで動かし始める」こと。", "kid": "カーネルはディスク(SSDなど)の中に、ただのファイルとして保存されている。ファイルのままでは動けないので、ブートローダがそのファイルを見つけ出し、メモリという「作業机」の上に広げて、動かし始める役目を持つ。", "eg": "たとえるなら、カーネルは「本棚にしまわれた台本」。ブートローダは「その台本を本棚から取り出して、演者(CPU)の前の机に広げる」係。机に広げて初めて、演者はセリフを読み始められる。", "terms": [["ブートローダ", "ディスクからカーネルを見つけて読み込み、実行を開始させるプログラム"], ["メモリ", "プログラムが実際に動くときに使う作業スペース。ディスクより読み書きが速い"]], "why_asked": "ブートローダとカーネルの役割の境目が曖昧なままだと、「OSが起動しない」トラブルの原因がブートローダ側かカーネル側かを判断できない。", "think": "ディスクの中のカーネルは「保存されているだけ」で、まだ動いてはいない状態。プログラムが動くには、CPUがアクセスできるメモリの上に置かれている必要がある。ブートローダはこの「ディスクからメモリへ運ぶ」という橋渡しをし、運び終えたらカーネルに実行の主導権を渡して自分の役目を終える。", "vs": "BIOS/UEFIと混同しやすいが、BIOS/UEFIは「点検して呼び出すだけ」、ブートローダは「実際にカーネルを読み込んで動かし始める」という、一歩進んだ実務を担当している。", "usecase": "OSを新しくインストールしたときや、複数のOSを切り替えて起動したいときに「どのカーネルを読み込むか」を選ばせる画面は、ブートローダが表示している。", "opt": ["正解。ディスクの中のカーネルをメモリに読み込み、実行を開始させるのがブートローダの役割。", "ネットワーク設定ファイルの編集は、OSが起動しきった後にユーザーやアプリケーションが行う作業であり、ブートローダの仕事ではない。", "コマンドの解釈・実行はシェルの仕事であり、ブートローダはまだシェルが動く前の段階を担当している。", "ファイル権限の計算・表示は、ファイルシステムを扱う仕組みの仕事であり、ブートローダの役割ではない。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"18\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"62\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">ディスク上の</text><text x=\"62\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">カーネル</text><line x1=\"108\" y1=\"52\" x2=\"121\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"125\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">ブートローダ</text><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">が読込み</text><line x1=\"215\" y1=\"52\" x2=\"228\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"232\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"278\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">メモリ上で</text><text x=\"278\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">実行開始</text></svg>"}'),

  ('linux-q128', 'ブートプロセスの流れ',
   'カーネルが起動を終えたあと、最初に生まれる1つのプロセス（PID 1）が必要な理由として最も適切なものはどれか。',
   NULL::text,
   '["すべてのプロセスの元締めとして、他のプロセスをそこから次々に生み出していくため", "通信速度を底上げするために、ネットワークの機能をまとめて有効化するため", "起動直後の見た目を整えるために、画面の解像度を自動で調整するため", "データを守るために、ディスクの空き容量を暗号化して保護するため"]',
   0, '[0]', 'single',
   '{"asked": "起動直後に生まれる最初のプロセス(PID 1)が必要な理由を選ぶ問題。", "point": "PID 1は「すべてのプロセスの大元」。ここから枝分かれするようにプロセスが増えていく。", "kid": "プロセスは「他のプロセスから生み出される(fork)」という決まりがある。でも一番最初は「生み出してくれる親」がまだ誰もいない。そこでカーネルが特別に、最初の1つのプロセス(PID 1)だけを直接立ち上げる。以降のプロセスは、みんなこのPID 1の子孫として増えていく。", "eg": "たとえるなら、家系図で一番上にいる「初代」のような存在。初代がいなければ、そこから枝分かれする家系そのものが始まらない。", "terms": [["PID 1", "起動直後にカーネルが直接立ち上げる、最初のプロセス。以降の全プロセスの祖先にあたる"], ["fork", "既にあるプロセスが自分の複製を作って、新しいプロセスを生み出す仕組み"]], "why_asked": "「プロセスは親から生まれる」というルール(プロセスという考え方で学んだ内容)だけを覚えていると、「では一番最初のプロセスはどこから生まれたのか」という疑問に答えられなくなる。ここを埋めておくことで理解が一本につながる。", "think": "通常のプロセスは必ず既存のプロセス(親)からforkして生まれる。しかし起動直後はまだプロセスが1つも存在しないので、このルールだけでは最初の1つを説明できない。そこでカーネルが例外的に、自分自身の手で最初のプロセスを直接起動する。これがPID 1であり、以降のすべてのプロセスはこのPID 1（またはその子孫）からforkして生まれていく。", "vs": "「プロセスは全部fork(既存プロセスの複製)から生まれる」という理解のままだと矛盾に感じるが、PID 1だけはカーネルが直接生み出す特別な1つ、という例外として押さえておく。", "usecase": "PID 1のプロセス(現代の多くのシステムではsystemd)が異常終了すると、システム全体が道連れで止まってしまう。「なぜPID 1だけは特別扱いされるか」を知っていると、この壊れやすさの理由が理解できる。", "opt": ["正解。以降の全プロセスの元締めとして、そこから次々にプロセスが生まれていくために必要。", "ネットワーク通信速度の向上は、PID 1という存在そのものの目的ではなく、別の仕組み(ネットワーク機能)が担う話。", "画面解像度の自動調整は、起動がかなり進んだ後にデスクトップ環境などが行う作業であり、PID 1の存在理由ではない。", "ディスクの暗号化保護は、ストレージまわりの別の仕組みが担当する話で、最初のプロセスが必要な理由ではない。"], "viz": "<svg viewBox=\"0 0 340 108\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"60\" y=\"20\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"35\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">カーネル起動完了</text><line x1=\"170\" y1=\"42\" x2=\"170\" y2=\"46\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"46\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.4\"/><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">PID 1が誕生</text><line x1=\"170\" y1=\"68\" x2=\"170\" y2=\"72\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"72\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"87\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">PID 1から子プロセスが増殖</text></svg>"}'),

  ('linux-q129', 'ブートプロセスの流れ',
   '現代の多くのLinuxシステムで、PID 1として動いているプロセスは何か。',
   NULL::text,
   '["systemd（サービスの起動・監視をまとめて担当する仕組み）", "ブートローダ", "BIOS/UEFI", "シェル（bashなどのコマンドを受け付けるプログラム）"]',
   0, '[0]', 'single',
   '{"asked": "現代のLinuxでPID 1を務めているプロセスの名前を選ぶ問題。", "point": "現代の多くのLinuxでは、PID 1の正体はsystemd。", "kid": "PID 1は「最初に生まれる特別なプロセス」という役割の名前であって、中身のプログラムは時代やディストリビューションによって違う。現代の多くのLinuxでは、その役目をsystemdというプログラムが担当している。", "eg": "たとえるなら、「初代社長」というポストに、実際は誰が座っているかという話。今の多くの会社ではそのポストに「systemdさん」が座っている、というイメージ。", "terms": [["systemd", "現代の多くのLinuxでPID 1を務め、サービスの起動・監視・依存関係の管理をまとめて担当する仕組み"]], "why_asked": "「systemdとサービス管理」で学んだsystemdが、実は起動プロセス全体の最初の1つ(PID 1)でもある、という点をつなげられているか確認する問題。", "think": "ブートプロセスの流れをたどると、カーネルが起動した直後に生まれる最初のプロセスがPID 1であり、そこから全プロセスが枝分かれしていく。この「最初のプロセス」という役割を、現代の多くのLinuxではsystemdというプログラムが果たしている。systemdはPID 1として、以降サービスの起動・監視といった「見守り役」の仕事も続けて担当する。", "vs": "ブートローダやBIOS/UEFIと混同しやすいが、それらはOSが起動する「前」の段階の係であり、systemd(PID 1)はカーネルが動き始めた「後」に登場する、OS側のプロセスである点が違う。", "usecase": "「なぜsystemdが落ちるとシステム全体が止まるのか」という疑問は、systemdがまさにPID 1（全プロセスの起点）を務めていることから説明できる。", "opt": ["正解。現代の多くのLinuxでPID 1を務め、サービスの起動・監視を担当するのがsystemd。", "ブートローダは、カーネルを読み込んで実行を渡した時点で役目を終える、OS起動前の係である。", "BIOS/UEFIは電源投入直後に動く最初のプログラムだが、OSのプロセスではなくPID 1にはならない。", "シェルはユーザーがコマンドを打つための対話用プログラムであり、システム全体の最初のプロセスとして起動するものではない。"], "viz": "<svg viewBox=\"0 0 340 108\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"60\" y=\"20\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"35\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">カーネル起動</text><line x1=\"170\" y1=\"42\" x2=\"170\" y2=\"46\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"46\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.4\"/><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">PID 1 = systemd</text><line x1=\"170\" y1=\"68\" x2=\"170\" y2=\"72\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"72\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"87\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">各種サービスを起動</text></svg>"}'),

  ('linux-q130', 'ブートプロセスの流れ',
   'パソコンの電源を入れてからログイン画面が表示されるまでの正しい順番はどれか。',
   NULL::text,
   '["BIOS/UEFI → ブートローダ → カーネル起動 → PID 1(systemd等)がサービスを起動", "カーネル起動 → BIOS/UEFI → ブートローダ → PID 1(systemd等)がサービスを起動", "ブートローダ → BIOS/UEFI → PID 1(systemd等)がサービスを起動 → カーネル起動", "PID 1(systemd等)がサービスを起動 → BIOS/UEFI → ブートローダ → カーネル起動"]',
   0, '[0]', 'single',
   '{"asked": "起動シーケンス全体の正しい順番を選ぶ問題。", "point": "順番は「点検役(BIOS/UEFI)→運び役(ブートローダ)→本体起動(カーネル)→見守り役(PID 1)」の一直線。", "kid": "これまで1問ずつ確認してきた工程を、全部つなげて順番通りに並べる問題。まず電源が入ってBIOS/UEFIが点検、次にブートローダがカーネルを運んで起動、最後にカーネルが最初のプロセス(PID 1、多くの場合systemd)を立ち上げて、そこから各種サービスやログイン画面が用意されていく。", "eg": "たとえるなら、「受付が点検(BIOS/UEFI)→運び屋が台本を届ける(ブートローダ)→本番の演者が舞台に立つ(カーネル)→現場監督が各部署に指示を出す(PID 1)」という一連の流れ。", "terms": [["起動シーケンス", "電源投入からログイン画面表示までの、決まった順番で進む一連の工程"]], "why_asked": "個別の工程は理解していても、全体の順番を一直線に並べられるかどうかは別の力。総合問題として、これまでの理解が線としてつながっているかを確認する。", "think": "それぞれの工程には「前の工程が終わっていないと始められない」という依存関係がある。BIOS/UEFIが点検を終えないとブートローダは呼び出されず、ブートローダがカーネルを読み込まないとカーネルは動き出さず、カーネルが起動を終えないとPID 1は生まれない。この依存の連鎖が、そのまま正しい順番になる。", "vs": "順番を入れ替えた選択肢は、いずれかの工程が「まだ存在しないもの」に依存してしまっている(例: カーネルが動く前にPID 1が生まれる、など)ため、依存関係の向きを確認すれば見分けられる。", "usecase": "起動が途中で止まるトラブルに遭遇したとき、「画面に何も映らない(BIOS/UEFIより前)」「OSを選ぶ画面で止まる(ブートローダ)」「エラーメッセージが流れて止まる(カーネルやサービス起動)」のように、この順番を知っていると止まっている場所のあたりがつけやすい。", "opt": ["正解。点検(BIOS/UEFI)→運搬(ブートローダ)→本体起動(カーネル)→見守り役の起動(PID 1)という依存の順番に沿っている。", "カーネルが最初に来ると、まだ何も読み込まれていない段階で本体が起動することになり、依存関係が逆転している。", "BIOS/UEFIより先にブートローダが来ると、点検も済んでいないのに次の係が呼び出されることになり、順番が崩れている。", "PID 1が最初に来ると、まだカーネルさえ起動していない段階でプロセスが生まれることになり、成立しない順番になっている。"], "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"60\" y=\"20\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"35\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">BIOS/UEFI</text><line x1=\"170\" y1=\"42\" x2=\"170\" y2=\"46\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"46\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">ブートローダ</text><line x1=\"170\" y1=\"68\" x2=\"170\" y2=\"72\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"72\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"87\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">カーネル起動</text><line x1=\"170\" y1=\"94\" x2=\"170\" y2=\"98\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><rect x=\"60\" y=\"98\" width=\"220\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.4\"/><text x=\"170\" y=\"113\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">PID1がサービス起動</text></svg>"}'),

  ('linux-q131', 'ブートプロセスの流れ',
   '動作中のLinuxパソコンで、電源ボタンを長押しして強制的に電源を切ると好ましくないとされる主な理由は何か。',
   NULL::text,
   '["書き込み中のデータやファイルシステムの整合性が崩れたまま止まってしまう可能性があるため", "BIOS/UEFIの設定内容が、強制的に工場出荷時の状態へ書き戻されてしまうため", "ブートローダのプログラムが壊れて、二度と起動できなくなってしまうため", "カーネルのファイルが、ディスクから完全に消去されてしまうため"]',
   0, '[0]', 'single',
   '{"asked": "動作中に強制電源断をすると良くない理由を選ぶ問題。", "point": "強制電源断が良くないのは、「書きかけ」の状態のまま処理が止まってしまう可能性があるから。", "kid": "パソコンが動いている間、ファイルは書き込みの途中だったり、複数のファイルをまとめて更新している途中だったりすることがある。その途中で急に電源が切れると、「半分だけ書き込まれた」ような中途半端な状態がディスクに残ってしまうことがある。", "eg": "たとえるなら、ノートに文章を書いている途中で、いきなりノートを取り上げられるようなもの。書きかけの文が残ったまま、続きが永遠に書けなくなってしまう。", "terms": [["ファイルシステムの整合性", "ディスク上のファイルやディレクトリの情報が、矛盾なく正しくつながっている状態"]], "why_asked": "「電源ボタンを押せばすぐ切れる」という感覚だけで操作すると、なぜそれがトラブルの原因になり得るのかが説明できない。ファイルシステムの本質(木構造・inode)を踏まえて理由づけできるか確認する問題。", "think": "ファイルシステムは、ファイルの中身だけでなく「どこに何があるか」という管理情報(前のカテゴリで触れたinodeなど)も同時に更新しながら動いている。通常のシャットダウンでは、動いているプロセスに終了の合図を送り、書きかけの処理を安全に終わらせてからディスクを外す、という手順を踏む。強制電源断はこの手順を全部すっ飛ばすため、管理情報とファイルの中身がずれた「中途半端な状態」のまま止まってしまう可能性がある。", "vs": "「電源を切る」という結果は同じでも、正常なシャットダウンは「後片付けをしてから切る」のに対し、強制電源断は「後片付けをせずいきなり切る」という手順の違いがある。", "usecase": "パソコンがフリーズして反応しないとき以外は、なるべく通常のシャットダウン操作を使うべきだという判断の裏付けになる。", "opt": ["正解。書き込み途中のデータやファイルシステムの管理情報が中途半端な状態のまま止まってしまう可能性があるため。", "BIOS/UEFIの設定は、強制電源断をしたからといって自動的に工場出荷時へ戻るような仕組みにはなっていない。", "ブートローダは通常のプログラムとして保存されており、強制電源断1回で二度と起動しなくなるようなものではない。", "カーネルのファイルは強制電源断によって自動的に消去されるようなものではなく、通常はそのままディスクに残っている。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6ab08d\">正常なシャットダウン</text><text x=\"250\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c47070\">強制電源断</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"90\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">処理を終わらせる</text><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">後片付けして切る</text><text x=\"250\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">処理の途中でも</text><text x=\"250\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">いきなり切れる</text></svg>"}'),

  ('linux-q132', 'リソース監視の基礎',
   'パソコンの動作が遅いとき、CPU・メモリ・ディスクなどの使用状況を確認する主な目的は何か。',
   NULL::text,
   '["「何が原因で遅いのか」を切り分けるための手がかりを得るため", "使用状況を確認するだけでパソコンの動作を自動的に速くするため", "壁紙やアイコンの表示速度を変更するため", "インターネットの契約プランを自動で見直すため"]',
   0, '[0]', 'single',
   '{"asked": "リソース使用状況を確認する目的を選ぶ問題。", "point": "監視の目的は「速くすること」自体ではなく、「原因を切り分ける手がかりを得ること」。", "kid": "パソコンが遅いとき、原因はいろいろありえる。計算しすぎて忙しい(CPU)のか、メモリが足りず苦しい(メモリ)のか、ディスクへの読み書きが渋滞している(ディスク)のか。使用状況を見ることで、「今、何が一番苦しそうか」の目星がつけられる。", "eg": "たとえるなら、体調が悪いときに体温・血圧・脈拍を測るようなもの。測ったからといって自動的に治るわけではないが、「熱が原因なのか、血圧が原因なのか」を絞り込む手がかりになる。", "terms": [["リソース監視", "CPU・メモリ・ディスクなど、コンピュータの資源(リソース)の使用状況を確認すること"]], "why_asked": "リソース監視を「見れば自動で直る魔法の操作」だと誤解していると、監視ツールを使っても次の行動につながらない。監視は「原因の切り分け」という次の一手のための材料である、という位置づけを理解しているか問う。", "think": "パソコンの「遅い」という現象1つにも、原因はCPU・メモリ・ディスク・ネットワークなど複数ありうる。原因を特定しないまま対策をしても的外れになりやすい。使用状況を数値で確認することで、「CPUの使用率が高いなら、重い処理が動いていないか調べる」「メモリが逼迫しているなら、メモリを大量に使うプロセスを探す」というように、次に調べるべき方向を絞り込める。これが監視の本来の役目である。", "vs": "「監視ツールを起動すること」自体と「原因を切り分けること」を混同しないこと。監視は手段であり、目的はあくまで原因の特定とその後の対処にある。", "usecase": "QA実務でテストが不安定になったとき、テストコード自体の問題か、実行環境のリソース不足(メモリ枯渇など)が原因かを切り分けるのにも、この考え方がそのまま使える。", "opt": ["正解。使用状況を見て、遅さの原因を切り分けるための手がかりを得ることが目的。", "使用状況を確認する行為そのものは観察であり、それだけで動作が自動的に速くなるような効果は持たない。", "壁紙やアイコンの表示速度は見た目の設定の話であり、リソースの使用状況確認とは直接関係しない。", "インターネットの契約プランの見直しは人間側の判断であり、リソース監視から自動的に行われるものではない。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"24\" text-anchor=\"middle\" font-size=\"12\" fill=\"#e8eaf0\">CPU使用率</text><rect x=\"40\" y=\"44\" width=\"260\" height=\"18\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><rect x=\"40\" y=\"44\" width=\"213\" height=\"18\" rx=\"4\" fill=\"#60a5fa\" opacity=\"0.55\"/><text x=\"170\" y=\"57\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">82%</text><text x=\"170\" y=\"86\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">高い=何かが処理を奪い合っている状態</text></svg>"}'),

  ('linux-q133', 'リソース監視の基礎',
   'メモリが不足してくると、パソコンの動作が遅くなることが多い。この現象がなぜ起きるかについて最も適切な説明はどれか。',
   NULL::text,
   '["メモリに収まりきらない分をディスクへ一時的に逃がす(スワップ)ようになり、遅いディスクへの読み書きが増えるため", "メモリが不足すると、CPUの計算速度そのものが自動的に半分近くまで落ちる仕組みになっているため", "メモリが不足すると、ネットワークの回線速度が自動的に大きく制限される仕組みになっているため", "メモリが不足すると、ファイルの権限(rwx)が自動的にすべて書き込み禁止へ変わる仕組みになっているため"]',
   0, '[0]', 'single',
   '{"asked": "メモリ不足で動作が遅くなる仕組みを選ぶ問題。", "point": "メモリ不足で遅くなるのは、足りない分を遅いディスクで肩代わりさせる「スワップ」が起きるから。", "kid": "メモリは「今すぐ使う作業机」で、とても速いけれど広さに限りがある。机に載せきれなくなると、一部の作業道具をディスクという「引き出し」に一時的にしまって、必要なときだけ取り出すようになる。この引き出しの出し入れ(スワップ)がメモリより何倍も遅いため、全体の動作がガクッと遅くなる。", "eg": "たとえるなら、机の上が散らかって置ききれなくなったので、道具を床下収納にしまい、使うたびに床板を開けて取り出すようなもの。取り出すたびに手間がかかり、作業全体が遅くなる。", "terms": [["スワップ", "メモリに入りきらないデータを、一時的にディスクへ逃がして空きを作る仕組み"]], "why_asked": "「メモリが足りないと遅くなる」という結果だけを覚えるのではなく、「なぜ遅くなるのか(スワップという迂回路が発生するから)」という因果を理解しているか問う。", "think": "メモリはディスクに比べて桁違いに速く読み書きできるが、容量には限りがある。使いたいデータの総量がメモリの容量を超えると、OSはあふれた分を一時的にディスクへ書き出し、必要になったらまた読み込む「スワップ」という仕組みで対応する。ディスクへのアクセスはメモリよりずっと時間がかかるため、スワップが頻発すると全体の動作が目に見えて遅くなる。これが「メモリ不足→遅い」という因果の中身。", "vs": "「メモリが足りないと壊れる・止まる」という誤解と違い、多くの場合はまず「遅くなる(スワップが増える)」という形で症状が現れる、という段階の違いを押さえておく。", "usecase": "テスト実行環境が特定の条件下だけ極端に遅くなるようなとき、メモリ使用量とスワップの発生状況を確認するのは、原因切り分けの定番の手順になる。", "opt": ["正解。メモリに入りきらない分をディスクへ逃がす(スワップ)ようになり、遅いディスクアクセスが増えるため遅くなる。", "CPUの計算速度そのものは、メモリ不足によって自動的に落ちるような仕組みにはなっていない。", "ネットワークの回線速度は、メモリの空き状況によって自動的に制限されるような仕組みではない。", "ファイル権限(rwx)は、メモリの空き状況とは無関係に管理されている情報であり、自動的に書き込み禁止になったりしない。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"18\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"62\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">メモリ</text><text x=\"62\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">あふれる</text><line x1=\"108\" y1=\"52\" x2=\"121\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"125\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">ディスクへ</text><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">退避</text><line x1=\"215\" y1=\"52\" x2=\"228\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"232\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"278\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">遅いので</text><text x=\"278\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">全体が重い</text></svg>"}'),

  ('linux-q134', 'リソース監視の基礎',
   '「CPU使用率が高い」という状態が意味することとして最も適切なものはどれか。',
   NULL::text,
   '["CPUの処理能力を、複数のプロセスが奪い合うようにフル活用している状態", "CPUの温度が異常に下がりすぎて、正常に動作できていない状態", "CPUがネットワークから切り離され、通信できなくなっている状態", "CPUがディスクの中身をすべて暗号化し終えて、待機している状態"]',
   0, '[0]', 'single',
   '{"asked": "CPU使用率が高いとはどういう状態かを選ぶ問題。", "point": "CPU使用率が高い＝CPUという限られた処理能力を、たくさんの仕事が奪い合ってフル稼働させている状態。", "kid": "CPUは「計算をする係」で、同時に処理できる仕事の数には限りがある。動いているプロセス(前のカテゴリで学んだ「プロセスという考え方」)が、次々にCPUへ計算をお願いしてくる。お願いの量がCPUの処理能力に対して多いほど、使用率は高くなる。", "eg": "たとえるなら、レジ係が1人しかいないお店に、お客さんが次々並ぶ状態。お客さんの数(処理の要求)が多いほど、レジ係(CPU)はずっと働きっぱなしで「使用率が高い」状態になる。", "terms": [["CPU使用率", "CPUの処理能力のうち、実際に計算に使われている割合"]], "why_asked": "「使用率が高い＝壊れている」という誤解をしていると、正常にたくさん処理をこなしているだけの状態を、故障だと勘違いしてしまう。", "think": "CPU使用率は「CPUが休んでいる時間の少なさ」を表す数値。プロセスがCPUに計算を頼むたびに、CPUはその処理をこなす。頼まれる量が増えるほど、CPUが手を止めている暇がなくなり、使用率は上がっていく。使用率が高いこと自体は「たくさん仕事をしている」という状態であって、故障や異常を直接意味するわけではない。ただし、想定外に高い状態が続く場合は、想定外の重い処理が動いていないかを調べる手がかりになる。", "vs": "「使用率が高い＝悪いこと」と単純に結びつけないこと。忙しく働いている証拠でもあるので、想定内の忙しさか、想定外の異常な忙しさかを区別して考える必要がある。", "usecase": "自動テストを大量に並列実行したときにCPU使用率が張り付くのは、想定の範囲内であることが多く、テストが不安定になる原因として「異常」と決めつける前に確認すべき情報になる。", "opt": ["正解。CPUという限られた処理能力を、複数のプロセスが奪い合うようにフル活用している状態を指す。", "CPUの温度低下による異常動作とは別の話で、CPU使用率という数値は温度そのものを表すものではない。", "ネットワークからの切断状態は、CPU使用率という指標が直接示すものではなく、別の確認方法が必要になる。", "ディスクの暗号化状況は、CPU使用率という指標とは無関係な、別のストレージまわりの話である。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"24\" text-anchor=\"middle\" font-size=\"12\" fill=\"#e8eaf0\">CPU使用率</text><rect x=\"40\" y=\"44\" width=\"260\" height=\"18\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><rect x=\"40\" y=\"44\" width=\"247\" height=\"18\" rx=\"4\" fill=\"#c47070\" opacity=\"0.55\"/><text x=\"170\" y=\"57\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">95%</text><text x=\"170\" y=\"86\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">処理の奪い合いが激しい状態</text></svg>"}'),

  ('linux-q135', 'リソース監視の基礎',
   'ディスクの空き容量を定期的に確認しておくべき理由として最も適切なものはどれか。',
   NULL::text,
   '["容量が尽きると、新しいファイルの書き込みやログの記録ができなくなり、様々な処理が失敗し始めるため", "ディスクの空き容量が減ると、CPUの計算速度が自動的に倍になる仕組みになっているため", "ディスクの空き容量が減ると、ネットワークの通信内容が自動的に暗号化される仕組みになっているため", "ディスクの空き容量が減ると、ファイルの所有者が自動的に変更される仕組みになっているため"]',
   0, '[0]', 'single',
   '{"asked": "ディスク容量を監視すべき理由を選ぶ問題。", "point": "ディスクが尽きて困るのは、「新しく書き込む」という当たり前の動作ができなくなるから。", "kid": "ファイルシステム(前のカテゴリで学んだ「ディスクとストレージの基礎」)には限りがある。空き容量がゼロに近づくと、新しいファイルを保存したり、ログを追記したりする「書き込み」という動作そのものができなくなり、色々な処理がそこでつまずいてしまう。", "eg": "たとえるなら、ノートのページがもう残っていない状態で、新しいメモを書こうとするようなもの。書くスペースがなければ、どんなに大事なメモでも書き留められない。", "terms": [["ディスクの空き容量", "ストレージのうち、まだ何も書き込まれていない使える領域の大きさ"]], "why_asked": "「容量が減っても動作が遅くなるだけ」という誤解と、「容量がゼロになると書き込みそのものができなくなる」という実際の挙動の違いを区別できているか問う。", "think": "メモリ不足は「遅くなる」という形で症状が出やすいのに対し、ディスクの空き容量不足は「そもそも書き込めない」という、より直接的なエラーとして現れやすい。ログファイルへの追記、テスト結果の保存、一時ファイルの作成など、様々な処理が「書き込み」を伴うため、容量が尽きるとそれらが一斉に失敗し始める。これが、ディスク容量を定期的に確認しておくべき理由。", "vs": "メモリ不足(遅くなる)とディスク容量不足(書き込みが失敗する)は、どちらも「足りなくなる」点は同じでも、現れる症状の種類が違う点に注意する。", "usecase": "CI環境でテスト結果やログの保存先が突然エラーになったとき、まずディスクの空き容量を疑う、というのはQA実務でもよくある切り分けの初手になる。", "opt": ["正解。容量が尽きると新しい書き込みができなくなり、様々な処理が失敗し始めるため。", "ディスクの空き容量とCPUの計算速度は別々の資源であり、容量が減ったからといって計算速度が自動的に倍になるようなことはない。", "ディスクの空き容量とネットワークの暗号化は無関係な仕組みであり、容量減少が暗号化を自動で発生させることはない。", "ファイルの所有者は権限の仕組みで管理されるものであり、ディスクの空き容量の増減によって自動的に変わるものではない。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"24\" text-anchor=\"middle\" font-size=\"12\" fill=\"#e8eaf0\">ディスク使用率</text><rect x=\"40\" y=\"44\" width=\"260\" height=\"18\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/><rect x=\"40\" y=\"44\" width=\"252\" height=\"18\" rx=\"4\" fill=\"#c47070\" opacity=\"0.55\"/><text x=\"170\" y=\"57\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">97%</text><text x=\"170\" y=\"86\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">空きがない＝新しく書き込めない</text></svg>"}'),

  ('linux-q136', 'リソース監視の基礎',
   'topのようなリソース監視ツールを「継続的に」動かして観察することの利点として最も適切なものはどれか。',
   NULL::text,
   '["一瞬だけ重かったのか、ずっと重い状態が続いているのかを見分けられる", "監視ツールを起動している間だけ、パソコンの動作が自動的に速くなる", "監視ツールを起動すると、不要なファイルが自動的に削除される", "監視ツールを起動すると、ネットワークの設定が自動的に最適化される"]',
   0, '[0]', 'single',
   '{"asked": "リソース監視を継続的に行う利点を選ぶ問題。", "point": "継続的に見る利点は、「一瞬の山」なのか「ずっと続く重さ」なのかを見分けられること。", "kid": "1回だけ数値を見ても、それがたまたまの一瞬なのか、ずっと続いている状態なのかは分からない。継続的に観察することで、「一瞬だけCPUが跳ねただけ」なのか「ずっとCPUが張り付いている」のかという、時間の流れの中での変化が見えるようになる。", "eg": "たとえるなら、体温を1回測っただけでは「今たまたま高いだけ」か「熱が続いている」か分からないのと同じ。何度か測って初めて、傾向が見えてくる。", "terms": [["継続的な監視", "一時点だけでなく、時間の経過に沿って繰り返し観察すること"]], "why_asked": "「一度確認すれば十分」という発想では、一時的な負荷と慢性的な問題を取り違えてしまう。監視は「点」ではなく「線」で見る必要があるという考え方を問う。", "think": "パソコンの負荷は常に一定ではなく、時間帯や実行中の処理によって上下する。1回のスナップショットだけでは、その瞬間がたまたま忙しかっただけなのか、日常的に負荷が高い状態なのかを区別できない。継続的に観察することで、「特定の処理を実行したときだけ跳ね上がる」「常に高止まりしている」といったパターンが見え、原因の絞り込みにつながる。", "vs": "「1回確認する」ことと「継続して観察する」ことは、得られる情報の質が違う。前者は今この瞬間の状態、後者は傾向やパターンを教えてくれる。", "usecase": "「特定のテストを実行したときだけメモリが急増する」というような再現性のある不具合の切り分けは、まさに継続的な観察があって初めて見えてくるパターン。", "opt": ["正解。時間の経過を追うことで、一瞬の負荷なのか継続的な負荷なのかを見分けられる。", "監視ツール自体はあくまで観察するためのプログラムであり、動かしている間にパソコンの動作を自動的に速くする効果はない。", "監視ツールの起動は、不要なファイルの削除のような掃除の機能を自動的に行うものではない。", "監視ツールの起動は、ネットワーク設定を自動的に最適化するような効果を持つものではない。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"18\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"62\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">1回だけ</text><text x=\"62\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">測定</text><line x1=\"108\" y1=\"52\" x2=\"121\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"125\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">一瞬か継続か</text><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">わからない</text><line x1=\"215\" y1=\"52\" x2=\"228\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"232\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"278\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">継続観察で</text><text x=\"278\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">傾向が見える</text></svg>"}'),

  ('linux-q137', 'ファイル検索とfind/xargsの考え方',
   'ディレクトリの階層が深く、目的のファイルがどこにあるか分からないとき、「探す」ための専用のコマンドがあると便利な理由は何か。',
   NULL::text,
   '["木構造のディレクトリを人間が1つずつ目で追うのは非効率で、条件を指定して機械的に探し出す方が速く確実だから", "「探す」コマンドを使うと、ファイルの中身がその場で自動的に書き換わって見つけやすくなる仕組みだから", "「探す」コマンドを使うと、ディスクの空き容量がそのぶん自動的に増えていく仕組みになっているから", "「探す」コマンドを使うと、ファイルの権限がその場で自動的にすべて緩められる仕組みになっているから"]',
   0, '[0]', 'single',
   '{"asked": "ファイル検索コマンドが便利な理由を選ぶ問題。", "point": "検索コマンドが便利なのは、木構造を人間が手で追うより、条件指定で機械的に探す方が速くて確実だから。", "kid": "ファイルシステム(前のカテゴリで学んだ木構造)は、枝分かれがどんどん深くなっていくことがある。「このファイル、どこに置いたっけ」というとき、フォルダを1つずつ手で開いて探すのはとても大変。条件(名前・更新日など)を指定して機械的に探し出すコマンドがあれば、深い階層でも一瞬で見つけられる。", "eg": "たとえるなら、大きな図書館で1冊の本を探すとき、棚を端から順に見て回るより、蔵書検索システムに書名を入力して探す方が圧倒的に速いのと同じ。", "terms": [["検索コマンド(find等)", "指定した条件に合うファイルを、ディレクトリの木構造をたどって機械的に探し出すコマンド"]], "why_asked": "「フォルダを開いて目で探す」という日常の操作の延長で考えていると、なぜ専用のコマンドが必要なのかがピンとこない。ディレクトリが深く・数が多くなったときのスケールの違いを理解しているか問う。", "think": "ファイルシステムは、前のカテゴリで学んだ通り木構造になっており、階層が深くなればなるほど、目的のファイルが埋もれる場所も増えていく。人間が1つずつフォルダを開いて確認する方法は、階層が浅いうちは問題にならないが、深く・数が多くなるほど非効率になっていく。条件を指定して探すコマンドは、この木構造全体を機械的にたどってくれるため、階層の深さに関わらず素早く確実に目的のファイルを見つけられる。", "vs": "「目で探す」ことと「条件指定で探す」ことは、少数のファイルなら差が小さいが、数が多く階層が深いほど差が開いていく、という規模の違いを意識しておく。", "usecase": "大量のログファイルの中から「昨日更新されたものだけ」を探し出すような場面は、目視ではまず不可能で、検索コマンドの条件指定がそのまま活きる。", "opt": ["正解。木構造を人間が手で追うより、条件指定で機械的に探す方が速く確実だから。", "検索コマンドはあくまで「探す」ことに専念する道具であり、ファイルの中身を自動的に書き換えるような効果は持たない。", "検索コマンドを使うこと自体が、ディスクの空き容量を増やす操作にはならない。探すことと容量の増減は無関係。", "検索コマンドを使うことで、ファイルの権限が自動的に変更されるようなことはない。権限は別の仕組みで管理されている。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"18\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"62\" y=\"51\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">深い木構造</text><line x1=\"108\" y1=\"52\" x2=\"121\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"125\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">目で探す</text><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">(大変)</text><line x1=\"215\" y1=\"52\" x2=\"228\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"232\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"278\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">条件指定で</text><text x=\"278\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">機械的に探す</text></svg>"}'),

  ('linux-q138', 'ファイル検索とfind/xargsの考え方',
   '「findのようなファイル検索コマンド」と「grepのような文字列検索コマンド」の違いとして最も適切なものはどれか。',
   NULL::text,
   '["findは「ファイルそのもの」を探し、grepは「ファイルの中身の文字列」を探す", "findはファイルの中身を探し、grepはファイルそのものを探す", "findとgrepはまったく同じ働きをする、名前が違うだけの同一のコマンドである", "findはネットワーク上のファイルだけを探し、grepはローカルのファイルだけを探す"]',
   0, '[0]', 'single',
   '{"asked": "ファイル検索とファイル内容の検索の役割の違いを選ぶ問題。", "point": "探す対象が違う。findは「ファイルそのもの」、grepは「ファイルの中身の文字列」。", "kid": "似たような「探す」コマンドでも、探している対象が違う。findは「こういう名前・こういう条件のファイルはどこ？」というファイル自体の在りかを探す。grep(テキスト処理の基本で学んだ)は、「このファイルの中に、この単語は書かれている？」という中身の文字列を探す。", "eg": "たとえるなら、findは「本棚から特定のタイトルの本を探す」作業。grepは「その本を開いて、特定の単語が書かれているページを探す」作業。探す場所も方法も違う。", "terms": [["find", "ファイル名・更新日などの条件で、ファイルそのものを探し出すコマンド"], ["grep", "ファイルの中身を読み、指定した文字列を含む行を探し出すコマンド"]], "why_asked": "どちらも「探す」という言葉でひとくくりにされがちだが、探す対象(ファイルそのものか、中身の文字列か)が全く違う。この区別ができないと、目的に合わないコマンドを選んでしまう。", "think": "「探したいもの」を最初に切り分けることが肝心。「特定の名前・種類・日付のファイルを見つけたい」ならfindの出番であり、ファイルの中身は見ない。一方「あるファイルの中に、特定の単語や設定が書かれているか知りたい」ならgrepの出番であり、ファイル名ではなく中身を読みにいく。この対象の違いが、2つのコマンドの役割分担を決めている。", "vs": "「両方とも“探す”コマンド」という共通点だけで覚えると混同しやすい。「ファイルの在りかを探す(find)」か「ファイルの中身を探す(grep)」かという、探す対象の違いで区別する。", "usecase": "「エラーログのファイルがどこにあるか分からない」ときはfind、「そのログファイルの中にどのエラーが書かれているか知りたい」ときはgrep、というように使い分ける。", "opt": ["正解。findはファイルそのものを探し、grepはファイルの中身の文字列を探す、という役割の違いがある。", "findとgrepの役割が入れ替わっており、findが中身を探し、grepがファイル自体を探すという説明は逆になっている。", "見た目や名前は違っても役割は全く別物であり、同一のコマンドの言い換えというわけではない。", "findもgrepも、ネットワーク上かローカルかで対象が分かれているわけではなく、この説明は両者の本質的な違いではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#60a5fa\">find</text><text x=\"250\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c9a04a\">grep</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"90\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">ファイルそのものを</text><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">名前や条件で探す</text><text x=\"250\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">ファイルの中身の</text><text x=\"250\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">文字列を探す</text></svg>"}'),

  ('linux-q139', 'ファイル検索とfind/xargsの考え方',
   '「ファイルを探す」処理と「見つけたファイルに対して何かする」処理を、あえて別の作業として分けて考えることには、どのような利点があるか。',
   NULL::text,
   '["探す条件と、後で行う処理を、それぞれ独立に自由に組み合わせられるようになる", "分けて考えると、ディスクの読み書き速度が自動的に倍になる仕組みになっている", "分けて考えると、ファイルの権限が自動的に一番強い設定になる仕組みになっている", "分けて考えると、探す処理そのものが不要になるくらい省略される"]',
   0, '[0]', 'single',
   '{"asked": "「探す」と「処理する」を分けて考える利点を選ぶ問題。", "point": "分けておく利点は、探す条件と後の処理を、それぞれ自由に組み合わせられること。", "kid": "「探すこと」と「見つけたものに何かすること」を1つの塊にしてしまうと、条件を変えるたびに全部作り直しになる。でも別々の部品として考えておけば、「探す条件」だけを変えたり、「見つけた後にする処理」だけを変えたりと、自由に組み合わせを変えられる。", "eg": "たとえるなら、「探す係」と「運ぶ係」を別の人にしておけば、探す条件を変えても運ぶ係はそのまま使い回せるし、運び先を変えても探す係はそのまま使い回せる、というイメージ。", "terms": [["組み合わせる", "小さな部品を別々に用意し、必要に応じてつなぎ合わせて使うこと（標準入出力とパイプで学んだUnix哲学の実践）"]], "why_asked": "「探す」と「処理する」を1つの巨大なコマンドにまとめてしまいたくなるが、それでは応用が利かない。標準入出力とパイプのカテゴリで学んだ「小さな部品を組み合わせる」考え方が、ここにも通じていることを確認する問題。", "think": "「探す」という作業と「見つけたものをどうするか」という作業は、本質的には別々の関心事である。これらを1つの決め打ちのコマンドにまとめてしまうと、条件や処理を変えたいたびにコマンドそのものを作り直す必要が出てくる。逆に、探す部分と処理する部分を別の部品として用意しておけば、探す条件だけ差し替えたり、処理の内容だけ差し替えたりと、自由な組み合わせが可能になる。これは標準入出力とパイプのカテゴリで学んだ「小さい部品を組み合わせる」という考え方の延長線上にある。", "vs": "「1つの万能コマンドを作る」発想と「小さい部品を組み合わせる」発想は対照的で、Linuxの世界では後者(組み合わせる発想)が重視されている。", "usecase": "「特定の条件のログファイルだけをまとめて別フォルダに移動する」ような作業は、探す条件と処理の中身を自由に組み合わせられることの分かりやすい応用例になる。", "opt": ["正解。探す条件と、後で行う処理を、それぞれ独立に自由に組み合わせられるようになる。", "作業を分けて考えること自体は設計上の話であり、ディスクの読み書き速度そのものを変える効果はない。", "作業を分けて考えることと、ファイルの権限設定は無関係であり、権限が自動的に強くなるようなことはない。", "分けて考えても「探す」処理自体はやはり必要であり、不要になるわけではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c47070\">1つに固めた場合</text><text x=\"250\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6ab08d\">分けた場合</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"90\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">条件を変えると</text><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">全部作り直し</text><text x=\"250\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">条件も処理も</text><text x=\"250\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">自由に組合せ</text></svg>"}'),

  ('linux-q140', 'ファイル検索とfind/xargsの考え方',
   'find（見つけたファイルの一覧を出す）とxargs（受け取ったものを次のコマンドの引数として渡す）を組み合わせるときの、xargsの役割として最も適切なものはどれか。',
   NULL::text,
   '["findが見つけたファイルの一覧を受け取り、それらを別のコマンドの「引数」として渡す橋渡し役", "findより先に動いて、探す条件そのものを勝手に一方的にすべて決めてしまう役", "見つかったファイルの中身を、先頭から1文字ずつ順番にすべて暗号化していく役", "見つかったファイルの権限を、確認なしに自動ですべて読み取り専用へ変更してしまう役"]',
   0, '[0]', 'single',
   '{"asked": "find と組み合わせて使うxargsの役割を選ぶ問題。", "point": "xargsの役割は、findが見つけた一覧を「別のコマンドへの引数」として橋渡しすること。", "kid": "findは「条件に合うファイルの一覧」を出すのが仕事で、それ自体では何も処理をしない。一方、多くのコマンドは「引数」という形でファイル名を直接渡してあげないと動かないものがある。xargsは、findが出した一覧を受け取って、それを次のコマンドの引数の形に変えて渡す、橋渡し役をする。", "eg": "たとえるなら、findは「該当する荷物のリストを作る係」。xargsは「そのリストを見ながら、荷物を1つずつ次の作業員(別のコマンド)の手に渡していく係」。", "terms": [["xargs", "受け取った一覧を、次のコマンドの引数として渡す橋渡し役のコマンド"], ["引数", "コマンドを実行するときに一緒に渡す、対象や条件を指定する情報"]], "why_asked": "findだけでファイルの一覧は出せても、それだけでは「見つけたファイルに対して何かする」ことができない。xargsがその隙間を埋める役割であることを理解しているか問う。", "think": "findの出力は「一覧」というデータであり、それ自体はまだ何のコマンドにも渡っていない状態。多くのコマンドを実行するには、対象を「引数」という決まった形で渡す必要がある。xargsは、findから受け取った一覧を1件ずつ取り出し、次のコマンドの引数として渡していく仲介役を果たす。これにより、「見つける(find)」と「処理する(別のコマンド)」という別々の部品が、xargsという橋を介してつながる。", "vs": "パイプ(標準入出力とパイプで学んだ)と役割が似ているように見えるが、パイプは「標準出力から標準入力へ」そのまま流すのに対し、xargsは受け取った内容を「引数」という別の形に変換して渡す点が違う。", "usecase": "「特定の条件のログファイルを一括で削除・移動する」といった作業は、findで対象を見つけ、xargsで実際の処理コマンドに橋渡しする、という組み合わせの典型例になる。", "opt": ["正解。findが見つけたファイルの一覧を受け取り、それらを別のコマンドの引数として渡す橋渡し役。", "xargsはfindの後に動いて受け取った結果を処理する役であり、findより先に動いて条件を決める役ではない。", "xargs自体にファイルの中身を暗号化するような機能はなく、あくまで引数として渡す橋渡し役に徹している。", "xargs自体にファイルの権限を自動的に変更するような機能はなく、権限の変更は別のコマンドが行う話である。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"18\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"62\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">find</text><text x=\"62\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">一覧を出す</text><line x1=\"108\" y1=\"52\" x2=\"121\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"125\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">xargs</text><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">引数へ変換</text><line x1=\"215\" y1=\"52\" x2=\"228\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"232\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"278\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">別コマンドで</text><text x=\"278\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">処理</text></svg>"}'),

  ('linux-q141', 'ファイル検索とfind/xargsの考え方',
   '標準入出力とパイプで学んだ「パイプでそのままつなぐ」方法と、findの結果をxargsで「引数として渡す」方法が、あえて別の仕組みとして用意されている理由は何か。',
   NULL::text,
   '["多くのコマンドは「標準入力からの文字の流れ」と「引数として渡された対象」を別々の方法で受け取る作りになっているため", "パイプの方が常に何倍も速く動作し、xargsは常に遅く動作するという、性能差だけの問題であるため", "パイプは日本語の文字列専用に作られ、xargsは英語の文字列専用に作られた、文字コードの違いによるものであるため", "パイプとxargsは実質的にまったく同じ動きをするだけの、単なる呼び方の違いにすぎないものであるため"]',
   0, '[0]', 'single',
   '{"asked": "パイプとxargsという2つの受け渡し方が別々に存在する理由を選ぶ問題。", "point": "受け取り方の違いに合わせて、渡し方も2種類用意されている。", "kid": "コマンドがデータを受け取る方法には大きく2種類ある。1つは「流れてくる文字をそのまま読む(標準入力)」方法、もう1つは「あらかじめ対象を指定してもらう(引数)」方法。コマンドによってどちらの受け取り方を想定しているかが違うため、渡す側にもパイプとxargsという2つの方法が用意されている。", "eg": "たとえるなら、ある窓口は「流れてくる書類をそのまま受け取る」方式、別の窓口は「あらかじめ書類の番号を指定してもらう」方式、というように受付の作法が違うようなもの。渡す側も相手の作法に合わせて渡し方を変える必要がある。", "terms": [["標準入力", "コマンドが受け取る、文字の流れとしてのデータの入り口"], ["引数", "コマンドの実行時に、対象や条件としてあらかじめ渡しておく情報"]], "why_asked": "「パイプで何でもつながる」と思っていると、findの結果をパイプでそのまま渡してもうまく動かないコマンドに出会ったとき、なぜ動かないのか理解できない。受け取り方の違いという根本の理由を押さえる問題。", "think": "コマンドの多くは、標準入力(流れてくる文字の連続)を読むように作られているものと、引数(あらかじめ指定された対象のリスト)を受け取るように作られているものに分かれる。パイプは前者(標準入力)向けの受け渡し方法であり、後者(引数)を必要とするコマンドにパイプでデータを流しても、期待通りに動かないことがある。xargsは、この「引数として渡してほしい」コマンドに対応するために、標準入力の内容を引数の形に変換して渡す役割を担っている。", "vs": "「パイプで何でも渡せる」という思い込みと、「コマンドによって受け取り方の作法が違う」という実際の事情を区別しておくと、うまく動かないときの原因がすぐに分かるようになる。", "usecase": "「パイプでそのままつないだのに期待通りに動かない」というつまずきに遭遇したとき、相手のコマンドが引数を必要とするタイプではないかを疑う、という切り分けにつながる。", "opt": ["正解。多くのコマンドは標準入力からの文字の流れと引数として渡された対象を別々の方法で受け取る作りになっているため。", "パイプとxargsの使い分けは、単純な速度の優劣だけで説明できるものではなく、受け取り方の違いという根本の理由がある。", "パイプとxargsの使い分けは、扱う言語や文字コードの違いによるものではない。", "パイプとxargsは、受け取り方の作法が異なるコマンドに対応するために別々に用意されている、役割の異なる仕組みである。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#60a5fa\">パイプ</text><text x=\"250\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c9a04a\">xargs</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"90\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">流れてくる文字を</text><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">そのまま読む相手向け</text><text x=\"250\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">引数として渡さないと</text><text x=\"250\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">受け取れない相手向け</text></svg>"}'),

  ('linux-q142', 'セキュリティの基礎',
   'サーバーで使っていないポートを閉じておくべき理由として最も適切なものはどれか。',
   NULL::text,
   '["開いているポートは外部から接続できる入口になるため、使っていない入口は攻撃の糸口になりうるから", "ポートを閉じると、サーバーのディスク容量が自動的に大きく増える仕組みになっているから", "ポートを閉じると、ファイルの所有者が自動的にすべて変更される仕組みになっているから", "ポートを閉じると、CPUの計算速度が自動的に大きく速くなる仕組みになっているから"]',
   0, '[0]', 'single',
   '{"asked": "使っていないポートを閉じておくべき理由を選ぶ問題。", "point": "開いているポートは「外から入れる入口」。使っていない入口を残すこと自体がリスクになる。", "kid": "ネットワークの基礎で学んだ通り、ポートはプロセスへの入口。開いているポートがあれば、外からそこにアクセスできてしまう。使っていないサービスのポートまで開けっぱなしにしておくと、本来使う予定のない入口を、悪意のある人に見つけられて悪用される可能性が生まれる。", "eg": "たとえるなら、家に使っていない勝手口をいくつも開けっぱなしにしているようなもの。普段使わないなら、鍵をかけて閉じておく方が安全に決まっている。", "terms": [["ポート", "ネットワーク越しに、特定のプロセスへアクセスするための番号付きの入口（ネットワークの基礎で既出）"]], "why_asked": "「ポートを閉じる」という操作を、単なるおまじないではなく「入口を減らす」という具体的な理由付きで理解できているか問う。ネットワークの基礎の知識をセキュリティの文脈につなげる問題。", "think": "ポートは前のカテゴリで学んだ通り、特定のプロセスにアクセスするための入口。開いているポートの数だけ、外部から侵入を試みられる入口の数が増える。使っていないサービスのポートを開けっぱなしにしていても、普段は誰も気づかず害がないように見えるが、その入口自体が「攻撃を試せる対象」として存在し続けてしまう。使っていないポートを閉じておくことは、攻撃者が試せる入口の数そのものを減らす、地味だが効果的な対策になる。", "vs": "「使っていないから安全」という思い込みと、「使っていなくても開いていれば入口になりうる」という実際のリスクを区別しておく。", "usecase": "テスト環境を一時的に外部公開するとき、必要なポートだけを開け、それ以外を閉じておくのは、テスト環境が思わぬ侵入経路にならないための基本的な備え。", "opt": ["正解。開いているポートは外部から接続できる入口になるため、使っていない入口は攻撃の糸口になりうる。", "ポートを閉じることと、ディスク容量の増減は無関係であり、閉じたからといって容量が自動的に増えることはない。", "ポートを閉じることと、ファイルの所有者の変更は別の仕組みであり、ポートを閉じても所有者が自動的に変わることはない。", "ポートを閉じることと、CPUの計算速度は無関係であり、閉じたからといって計算速度が自動的に上がることはない。"], "viz": "<svg viewBox=\"0 0 340 112\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">サーバー</text><rect x=\"30\" y=\"26\" width=\"280\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><circle cx=\"55\" cy=\"56\" r=\"12\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.6\"/><text x=\"55\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#6ab08d\">80番</text><text x=\"55\" y=\"100\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">開放</text><circle cx=\"115\" cy=\"56\" r=\"12\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.6\"/><line x1=\"107\" y1=\"48\" x2=\"123\" y2=\"64\" stroke=\"#c47070\" stroke-width=\"1.4\"/><text x=\"115\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c47070\">22番</text><text x=\"115\" y=\"100\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">遮断</text><circle cx=\"175\" cy=\"56\" r=\"12\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.6\"/><line x1=\"167\" y1=\"48\" x2=\"183\" y2=\"64\" stroke=\"#c47070\" stroke-width=\"1.4\"/><text x=\"175\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c47070\">使わないport</text><text x=\"175\" y=\"100\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">遮断</text></svg>"}'),

  ('linux-q143', 'セキュリティの基礎',
   'ファイアウォールが果たす役割として最も適切なものはどれか。',
   NULL::text,
   '["通信を条件に照らして、通してよいものだけを許可し、それ以外を遮断するフィルタ", "保存されたファイルの中身を読み取り、自動的に要約して短くまとめる仕組み", "サーバーのディスクの空き容量を監視し、自動的に増やしていく仕組み", "登録されているパスワードを、定期的に自動で変更していく仕組み"]',
   0, '[0]', 'single',
   '{"asked": "ファイアウォールの役割を選ぶ問題。", "point": "ファイアウォールは、通信の「通してよい・悪い」を条件で判定するフィルタ。", "kid": "ファイアウォールは、外部やり取りされる通信の1つ1つを見て、「この通信は通してよい」「この通信は怪しいから止める」と条件に照らして判定する、門番のような仕組み。あらかじめ決めたルールに合わない通信を機械的に遮断する。", "eg": "たとえるなら、マンションの管理人が、来訪者の名簿(条件)と照らし合わせて、名簿にある人だけ通し、それ以外の人は入り口で止めるようなもの。", "terms": [["ファイアウォール", "通信を条件に照らして許可・遮断を判定するフィルタの仕組み"]], "why_asked": "「ファイアウォール＝なんとなく安全にしてくれる魔法の箱」という曖昧な理解ではなく、「条件で通信を判定するフィルタ」という具体的な役割を理解しているか問う。", "think": "ポートを閉じることは「入口そのものを塞ぐ」対策だったのに対し、ファイアウォールは「入ってこようとする通信を、条件に応じて選別する」対策であり、両者は補い合う関係にある。ファイアウォールにあらかじめルール(どの相手からの、どのポートへの通信を許可するか)を設定しておくことで、想定外の通信が来たときに自動的に遮断できるようになる。", "vs": "「ポートを閉じる」ことと「ファイアウォールで制御する」ことは似ているが、前者は入口自体を無くす対策、後者は入口を残したまま通信内容で選別する対策という違いがある。", "usecase": "テスト環境を社内ネットワークからだけアクセスできるようにしたいとき、ファイアウォールで「社内のIPアドレスからの通信だけ許可する」というルールを設定するのは典型的な使い方。", "opt": ["正解。通信を条件に照らして、通してよいものだけを許可し、それ以外を遮断するフィルタの役割を果たす。", "ファイルの中身の自動要約は、ファイアウォールの役割とは別の、文書処理の話である。", "ディスクの空き容量を自動的に増やすことは、ファイアウォールの役割ではなく、ストレージ管理の話である。", "パスワードの定期的な自動変更は、ファイアウォールの役割ではなく、アカウント管理の仕組みの話である。"], "viz": "<svg viewBox=\"0 0 340 112\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">サーバー</text><rect x=\"30\" y=\"26\" width=\"280\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><circle cx=\"55\" cy=\"56\" r=\"12\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.6\"/><text x=\"55\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#6ab08d\">許可された|通信</text><text x=\"55\" y=\"100\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">開放</text><circle cx=\"115\" cy=\"56\" r=\"12\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.6\"/><line x1=\"107\" y1=\"48\" x2=\"123\" y2=\"64\" stroke=\"#c47070\" stroke-width=\"1.4\"/><text x=\"115\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c47070\">怪しい通信</text><text x=\"115\" y=\"100\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">遮断</text></svg>"}'),

  ('linux-q144', 'セキュリティの基礎',
   '「最小権限の原則」という考え方の説明として最も適切なものはどれか。',
   NULL::text,
   '["各ユーザーやプロセスには、本当に必要な範囲の権限だけを与え、それ以上は与えない", "すべてのユーザーに対して、あらかじめ最大限の権限をまとめて与えておく", "権限という概念そのものを廃止して、誰もが何でもできるようにしておく", "権限は最初に一度与えたら、その後は二度と見直さずそのまま使い続ける"]',
   0, '[0]', 'single',
   '{"asked": "最小権限の原則の考え方を選ぶ問題。", "point": "最小権限の原則は「必要な分だけ渡す」という考え方。多く渡しすぎない。", "kid": "権限とユーザーで学んだ通り、権限は「何をしてよいか」の範囲を決めるもの。最小権限の原則は、「その人・そのプログラムが本当に必要としている分だけ権限を渡し、それ以上は渡さない」という考え方。多めに渡しておいた方が便利そうに見えても、あえてそうしない。", "eg": "たとえるなら、アルバイトのスタッフに、レジの操作権限は渡すけれど、店の金庫の暗証番号までは渡さないようなもの。仕事に必要な範囲だけを渡す。", "terms": [["最小権限の原則", "本当に必要な範囲の権限だけを与え、それ以上は与えないという考え方"]], "why_asked": "「権限は多い方が便利」という直感と、セキュリティの観点で「必要以上に渡さない」という考え方が対立する場面。なぜあえて不便になりうる制限をかけるのか、その理由を理解しているか問う。", "think": "権限を必要以上に広く与えておくと、そのユーザーやプロセスが乗っ取られたり誤操作をしたりしたときに、被害の範囲がそのまま権限の広さに比例して大きくなってしまう。逆に、本当に必要な範囲だけに権限を絞っておけば、何か問題が起きても被害が限られた範囲にとどまりやすい。多少不便になっても、この「被害を小さく抑える」効果を優先するのが最小権限の原則の考え方である。", "vs": "「便利さを優先して権限を広く渡す」発想と、「安全性を優先して権限を絞る」発想は対立するが、セキュリティの基本ではあえて後者を選ぶ、という優先順位の違いを理解しておく。", "usecase": "テスト自動化のスクリプトに、本番データベースへの書き込み権限まで不必要に持たせないようにするのも、最小権限の原則の実践例になる。", "opt": ["正解。各ユーザーやプロセスには、本当に必要な範囲の権限だけを与え、それ以上は与えないという考え方。", "最大限の権限をあらかじめ与えておく発想は、最小権限の原則とは正反対の考え方である。", "権限という概念自体をなくすことは、最小権限の原則とは異なり、むしろ権限管理を放棄することになる。", "権限を一度与えたきり見直さない運用は、最小権限の原則が重視する「必要な範囲に保つ」という継続的な意識と噛み合わない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c47070\">必要以上に渡す</text><text x=\"250\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6ab08d\">最小権限</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"90\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">便利そうに見える</text><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">被害の範囲も広がる</text><text x=\"250\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">必要な分だけ</text><text x=\"250\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">被害を限定できる</text></svg>"}'),

  ('linux-q145', 'セキュリティの基礎',
   '動いているサービスの中で、実際には使っていないものを止めておくべき理由として最も適切なものはどれか。',
   NULL::text,
   '["動いているサービスはそれぞれ攻撃の対象になりうるため、使っていないものは止めて対象を減らす方がよい", "サービスを止めると、そのサーバーのCPU性能が自動的に2倍近くまで上がる仕組みになっているため", "サービスを止めると、ディスクの中身がすべて自動的にバックアップされる仕組みになっているため", "サービスを止めると、ネットワークのIPアドレスが自動的にすべて変わる仕組みになっているため"]',
   0, '[0]', 'single',
   '{"asked": "使っていないサービスを止めておくべき理由を選ぶ問題。", "point": "動いているサービス1つ1つが、攻撃を試される対象になりうる。使わないなら止める方が安全。", "kid": "systemdとサービス管理で学んだ通り、サービスは裏でずっと動き続けるプログラム。動いているサービスがあるということは、それだけ外部からのアクセスを受け付けている可能性があるということ。使っていないサービスまで動かし続けていると、そのぶん攻撃の対象になりうる場所が増えてしまう。", "eg": "たとえるなら、使っていない部屋の電気やドアの鍵をつけっぱなしにしておくと、それだけ管理しなければいけない場所が増えるようなもの。使わないなら閉じておく方が安全で楽。", "terms": [["攻撃対象領域", "外部から攻撃を試みられる可能性のある入口や仕組み全体のこと"]], "why_asked": "ポートを閉じる理由と似た発想だが、「サービス(プロセス)」という単位でも同じ考え方が成り立つことを理解しているか問う。ネットワークの基礎とsystemdの両方の理解をつなげる問題。", "think": "使っていないポートを閉じる理由と本質的には同じで、動いているサービスの数だけ、外部から攻撃を試みられる可能性のある対象が増える。サービスを1つ止めれば、それに紐づくポートやプロセスも一緒に無くなるため、攻撃対象になりうる場所を丸ごと1つ減らすことができる。「使っていないなら止める」というシンプルな判断が、地味だが効果的なセキュリティ対策になる。", "vs": "「ポートを閉じる」対策と「サービスを止める」対策は似ているが、サービスを止めればそれに紐づくポートごと無くなるため、より根本的な対策になる点が違う。", "usecase": "テスト用に一時的に立ち上げたサービスを、テストが終わった後も動かしっぱなしにせず、使い終わったら止める習慣は、このセキュリティの考え方の日常的な実践になる。", "opt": ["正解。動いているサービスはそれぞれ攻撃の対象になりうるため、使っていないものは止めて対象を減らす方がよい。", "サービスを止めることと、CPU性能が自動的に2倍になることは無関係であり、そのような効果はない。", "サービスを止めることと、ディスクの中身が自動的にバックアップされることは無関係であり、そのような効果はない。", "サービスを止めることと、ネットワークのIPアドレスが自動的に変わることは無関係であり、そのような効果はない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c47070\">使っていないサービスも稼働</text><text x=\"250\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6ab08d\">不要なサービスは停止</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"90\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">攻撃対象が多い</text><text x=\"250\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">攻撃対象が少ない</text></svg>"}'),

  ('linux-q146', 'セキュリティの基礎',
   '普段の作業でrootユーザーとして常時ログインし続けることが避けられる理由として最も適切なものはどれか。',
   NULL::text,
   '["誤操作や乗っ取りが起きたときに、被害の範囲がシステム全体に及んでしまう可能性が高いため", "rootユーザーは、パスワードを設定できない特殊な仕組みになっているため", "rootユーザーでログインすると、ネットワーク接続が自動的に切断されるため", "rootユーザーでログインすると、ファイルがすべて自動的に読み取り専用になるため"]',
   0, '[0]', 'single',
   '{"asked": "普段からrootで作業しない方がよい理由を選ぶ問題。", "point": "rootは全部できてしまう分、間違えたときの被害範囲も一番大きくなる。", "kid": "権限とユーザーで学んだ通り、rootはあらゆる操作ができる特別なユーザー。便利に見えるけれど、その分、うっかりコマンドを打ち間違えたときや、誰かに乗っ取られたときの被害も、システム全体に及んでしまう。普段の作業は必要最小限の権限で行い、本当に必要なときだけrootの力を借りる方が安全。", "eg": "たとえるなら、家中どの部屋の鍵も開けられるマスターキーを、普段の買い物にまで持ち歩くようなもの。落としたり盗まれたりしたときのリスクが大きすぎる。", "terms": [["root", "システム上のあらゆる操作ができる特別なユーザー（権限とユーザーで既出）"]], "why_asked": "「rootならなんでもできて便利」という発想と、「便利さの裏には被害範囲の大きさというリスクがある」という考え方を対比させ、最小権限の原則がrootという具体的な存在にどう当てはまるかを問う。", "think": "rootは、ファイルの削除から他のユーザーの権限変更まで、あらゆる操作を制限なく行える。この万能さは、正しく使えば便利だが、誤操作や乗っ取りが起きたときには、通常のユーザー権限では起こりえないレベルの被害(システム全体のファイルの破壊など)につながってしまう。普段の作業を一般ユーザーの権限で行い、必要なときだけ一時的にroot相当の権限を借りるようにすれば、うっかりミスや侵害の影響範囲を、日常的な作業の範囲に抑えられる。これはまさに最小権限の原則をrootという具体的な存在に当てはめた実践である。", "vs": "「rootを使わない」わけではなく、「常時ログインし続けない」という点が重要。本当に必要な操作のときだけ一時的に権限を借りる、という使い方が推奨される。", "usecase": "自動テストのスクリプトを普段からroot権限で動かしていると、スクリプトのバグが即座にシステム全体に影響しかねない。必要最小限の権限で動かす習慣は、QA実務でも被害を防ぐ工夫になる。", "opt": ["正解。誤操作や乗っ取りが起きたときに、被害の範囲がシステム全体に及んでしまう可能性が高いため。", "rootユーザーにパスワードを設定できないという制約は実際には存在せず、この説明は事実と異なる。", "rootユーザーでログインすることと、ネットワーク接続が自動的に切断されることは無関係であり、そのような仕組みはない。", "rootユーザーでログインすることと、ファイルが自動的に読み取り専用になることは無関係であり、そのような仕組みはない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c47070\">root常用</text><text x=\"250\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6ab08d\">必要な時だけroot</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"90\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">ミスも侵害も</text><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">被害が全体に</text><text x=\"250\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">普段は限定的な</text><text x=\"250\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">権限で作業</text></svg>"}'),

  ('linux-q147', 'セキュリティの基礎',
   'OSやソフトウェアを定期的にアップデートしておくことが、セキュリティの観点で重要とされる理由は何か。',
   NULL::text,
   '["過去に見つかった弱点(脆弱性)がアップデートで修正されており、放置すると既知の弱点を突かれる可能性があるため", "アップデートを適用するたびに、ディスクの空き容量がそのつど自動的に2倍近くまで増えていってしまうため", "アップデートを適用するたびに、搭載しているCPUの型番そのものが自動的に新しく置き換わってしまうため", "アップデートを適用するたびに、すべてのファイルの権限がそのつど自動的にリセットされてしまうため"]',
   0, '[0]', 'single',
   '{"asked": "定期的なアップデートがセキュリティ上重要な理由を選ぶ問題。", "point": "アップデートの実体は「見つかった弱点をふさぐ」こと。放置は、直せる穴を放置することになる。", "kid": "パッケージ管理の考え方で学んだ通り、ソフトウェアはパッケージという単位で管理・更新される。ソフトウェアには、後から「ここに弱点があった」と見つかることがある。アップデートには、その弱点を直す修正が含まれていることが多く、アップデートしないままでいると、すでに知られている弱点をそのまま放置し続けることになる。", "eg": "たとえるなら、家の鍵に「実はこの型は簡単に開けられる」という欠陥が見つかり、新型の鍵(アップデート)が用意されたのに、古い鍵のまま使い続けているようなもの。直せる欠陥を放置しているのと同じ。", "terms": [["脆弱性", "ソフトウェアに存在する、悪用されうる弱点・欠陥"], ["アップデート", "見つかった不具合や脆弱性を修正した、新しいバージョンへの更新"]], "why_asked": "「アップデートは新機能が増えるだけ」という理解に留まっていると、セキュリティ対策としての側面を見落としてしまう。アップデートが「弱点を直す」行為でもあるという理解を問う。", "think": "ソフトウェアが世に出た後、使われていく中で「ここに弱点があった」と発見されることがある。この弱点(脆弱性)は、悪用されると不正アクセスやデータ漏洩につながりうる。ソフトウェアの開発元は、こうした弱点が見つかると修正を行い、それをアップデートという形で配布する。アップデートを適用しないままでいることは、すでに世の中に知られている弱点を、自分のシステムにだけ残し続けることを意味し、攻撃を試みる側にとって狙いやすい対象になってしまう。", "vs": "「アップデート＝機能が増えるだけの作業」という見方と、「アップデート＝既知の弱点を塞ぐセキュリティ対策でもある」という見方を、両方とも持っておく必要がある。", "usecase": "テスト環境を長期間アップデートせずに放置していると、本番環境よりも先に弱点を突かれる入口になりかねない。定期的な更新はテスト環境にも同じように重要になる。", "opt": ["正解。過去に見つかった弱点(脆弱性)がアップデートで修正されており、放置すると既知の弱点を突かれる可能性があるため。", "アップデートによってディスクの空き容量が自動的に2倍に増えるような効果はない。", "アップデートによってCPUの型番そのものが新しくなるような効果はなく、ハードウェアは変わらない。", "アップデートによってすべてのファイルの権限が自動的にリセットされるような効果はない。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"18\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"62\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">弱点が</text><text x=\"62\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">見つかる</text><line x1=\"108\" y1=\"52\" x2=\"121\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"125\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">アップデート</text><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">で修正</text><line x1=\"215\" y1=\"52\" x2=\"228\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"232\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"278\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">適用しないと</text><text x=\"278\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">弱点が残る</text></svg>"}'),

  ('linux-q148', 'Gitとバージョン管理の基礎',
   'ファイルの変更履歴を残す仕組み（バージョン管理）が無いと、どのようなことに困るか。',
   NULL::text,
   '["「誰が」「いつ」「何を」変更したのかが分からなくなり、問題が起きたときに原因や差し戻し先を特定しづらくなる", "バージョン管理が無いと、ファイルを保存するという基本操作そのものが一切できなくなってしまう", "バージョン管理が無いと、ディスクの空き容量そのものが常に不足した状態のままずっと続いてしまう", "バージョン管理が無いと、ネットワークへの接続そのものがまったくできなくなってしまう"]',
   0, '[0]', 'single',
   '{"asked": "バージョン管理が無いと何に困るかを選ぶ問題。", "point": "バージョン管理が無いと困るのは、「誰が・いつ・何を変えたか」を後から追えなくなること。", "kid": "何人かで同じファイルを触っていると、「あれ、いつの間にか動かなくなった」ということが起きる。バージョン管理という仕組みが無いと、「誰が」「いつ」「何を」変えたせいでそうなったのかを後から調べる手立てがなくなってしまう。", "eg": "たとえるなら、みんなで1冊のノートに書き込んでいて、誰がどこを書き換えたか記録が一切残っていない状態。何かおかしくなっても、犯人も原因も分からない。", "terms": [["バージョン管理", "ファイルの変更履歴（誰が・いつ・何を変えたか）を記録し、後から追跡・差し戻しできるようにする仕組み"]], "why_asked": "Gitという固有の名前を覚える前に、そもそも「なぜバージョン管理という仕組みそのものが必要なのか」を、困りごとから理解できているか問う。", "think": "複数人、あるいは自分1人であっても、ファイルは時間とともに何度も書き換えられていく。変更履歴が残っていなければ、ある時点で問題が発生したときに、「どの変更が原因だったのか」「問題が起きる前の状態はどうだったのか」を突き止める手段がない。バージョン管理は、変更のたびに「誰が・いつ・何を」変えたかを記録しておくことで、この「原因究明」と「元に戻す」という2つの作業を可能にする仕組みである。", "vs": "「ファイルを保存すること」自体と「変更履歴を残すこと」は別の話。普通に保存しているだけでは、上書きされた過去の状態は消えてしまう。", "usecase": "テスト自動化のコードが急に失敗するようになったとき、「いつ・誰の変更から失敗し始めたか」を履歴から追えることは、原因調査を大きく助ける。", "opt": ["正解。「誰が」「いつ」「何を」変更したのかが分からなくなり、問題が起きたときに原因や差し戻し先を特定しづらくなる。", "バージョン管理が無くても、ファイルの保存という基本的な操作自体は変わらず可能である。", "バージョン管理の有無と、ディスクの空き容量が常に足りるかどうかは、直接結びつく話ではない。", "バージョン管理の有無と、ネットワークに接続できるかどうかは、まったく別の話である。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c47070\">履歴なし</text><text x=\"250\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6ab08d\">履歴あり</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"90\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">誰が変えたか</text><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">分からない</text><text x=\"250\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">誰が・いつ・何を</text><text x=\"250\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">追跡できる</text></svg>"}'),

  ('linux-q149', 'Gitとバージョン管理の基礎',
   'Gitが「分散型」のバージョン管理と呼ばれる理由として最も適切なものはどれか。',
   NULL::text,
   '["変更履歴の完全なコピーを、関わる人それぞれの手元(パソコン)にも持てる仕組みになっているため", "Gitを使うと、ファイルが自動的に世界中のサーバーへ分散してバックアップされるため", "Gitを使うと、1つのファイルが自動的に複数の異なるファイル形式に変換されるため", "Gitを使うと、複数人が同時に同じ行を編集しても、必ず自動的に正しい結果にまとまるため"]',
   0, '[0]', 'single',
   '{"asked": "Gitが分散型と呼ばれる理由を選ぶ問題。", "point": "分散型の意味は「履歴の完全なコピーを、各自の手元にも持てる」という点。", "kid": "バージョン管理の仕組みには、大きく分けて「1か所にだけ全部の履歴を置く」やり方と、「関わる人それぞれの手元にも、全部の履歴のコピーを持てる」やり方がある。Gitは後者で、自分のパソコンの中にも、変更履歴のまるごとコピーを持てるようになっている。だから「分散型」と呼ばれる。", "eg": "たとえるなら、図書館に1冊しかない本(集中型)ではなく、関わる人それぞれが同じ本の複製を1冊ずつ持っている(分散型)ようなもの。誰か1人の本が読めなくなっても、他の人の本で内容を確認できる。", "terms": [["分散型バージョン管理", "変更履歴の完全なコピーを、関わる人それぞれの手元にも持てる方式"], ["集中型バージョン管理", "変更履歴を1か所のサーバーにだけ置く、Gitとは異なる方式"]], "why_asked": "「Git＝クラウド上で共有するツール」という漠然としたイメージだけだと、「分散型」という言葉の意味が説明できない。手元に履歴のコピーがある、という具体的な仕組みを理解しているか問う。", "think": "「分散」という言葉は、データがバラバラに散らばるという意味ではなく、「同じ履歴の完全なコピーを、複数の場所(各自のパソコン)にそれぞれ持てる」という意味で使われている。これにより、ネットワークにつながっていない状態でも自分の手元の履歴を確認したり、過去の状態に戻したりする作業ができる。中央のサーバーが一時的に使えなくなっても、各自の手元に履歴のコピーが残っている、という点も分散型の特徴として挙げられる。", "vs": "「バックアップとして世界中に散らばる」という誤解と、「関わる人の手元にそれぞれ完全なコピーがある」という実際の意味を区別しておく。", "usecase": "オフライン環境でも、自分のパソコンにある履歴を使って過去の変更を確認できるのは、分散型という設計のおかげである。", "opt": ["正解。変更履歴の完全なコピーを、関わる人それぞれの手元(パソコン)にも持てる仕組みになっているため。", "Gitを使ったからといって、ファイルが自動的に世界中のサーバーへ分散してバックアップされるわけではない。", "Gitを使ったからといって、1つのファイルが自動的に複数の異なるファイル形式に変換されるわけではない。", "複数人が同じ行を編集した場合、Gitは矛盾(コンフリクト)として検出することはあっても、必ず自動的に正しくまとめてくれるわけではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#60a5fa\">集中型</text><text x=\"250\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c9a04a\">分散型(Git)</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"90\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">履歴は1か所だけ</text><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">そこが止まると困る</text><text x=\"250\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">各自の手元にも</text><text x=\"250\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">履歴の複製がある</text></svg>"}'),

  ('linux-q150', 'Gitとバージョン管理の基礎',
   'Gitにおける「コミット」がどのような単位を表しているかについて最も適切なものはどれか。',
   NULL::text,
   '["ある時点での変更内容をひとまとめにして記録した、履歴上のスナップショット", "ファイルを完全に削除して、復元できない状態にしてしまう操作", "ネットワーク回線がつながっているかを確認する、接続テストの操作", "ディスクの空き容量を計算して、画面に表示するだけの操作"]',
   0, '[0]', 'single',
   '{"asked": "Gitの「コミット」が何を表す単位かを選ぶ問題。", "point": "コミットは、ある時点の変更をまとめて記録した「1つの区切り」。", "kid": "作業をしていると、少しずつファイルの中身が変わっていく。その変化を「ここまでで一区切り」というタイミングでまとめて記録したものがコミット。1回のコミットが、履歴の中の1つの節目になる。", "eg": "たとえるなら、旅の途中で節目ごとに写真を1枚撮っておくようなもの。後から写真(コミット)を見返せば、「この時点ではこうだった」という状態を振り返れる。", "terms": [["コミット", "ある時点での変更内容をひとまとめにして記録した、履歴上の区切り"]], "why_asked": "「保存」と「コミット」を同じものだと思っていると、こまめに保存しているのにGitの履歴には何も残っていない、という食い違いに戸惑う。両者が別の操作であることを理解しているか問う。", "think": "普段ファイルを「保存」する操作は、今の状態を上書きするだけで、過去の状態は残らない。一方コミットは、「この時点までの変更をひとまとめにして、履歴に刻む」という別の操作であり、コミットするたびに履歴上の新しい区切り(スナップショット)が積み重なっていく。この積み重ねがあるからこそ、後から「あの時点まで戻る」「どこで何が変わったか確認する」ということができるようになる。", "vs": "ファイルの「保存」とGitの「コミット」は別の操作。保存しただけでは履歴に残らず、コミットして初めて履歴上の1つの記録として刻まれる。", "usecase": "「昨日までは動いていたのに今日動かない」という不具合調査で、コミットの履歴をさかのぼって「どのコミットから壊れたか」を特定する、という使い方は開発・QAの現場で頻繁に行われる。", "opt": ["正解。ある時点での変更内容をひとまとめにして記録した、履歴上のスナップショットを表す単位。", "コミットはファイルを削除して復元不可能にする操作ではなく、むしろ後から状態を振り返れるようにする記録の操作である。", "コミットはネットワーク回線の接続テストとは無関係な、変更履歴を記録するための操作である。", "コミットはディスクの空き容量を計算する操作ではなく、変更履歴を記録するための操作である。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">コミットの積み重ね</text><line x1=\"40\" y1=\"70\" x2=\"300\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.6\"/><circle cx=\"60\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"110\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"160\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"300\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><text x=\"170\" y=\"90\" text-anchor=\"middle\" font-size=\"9\" fill=\"#60a5fa\">main（本流）</text><path d=\"M160,70 C 200,70 220,110 260,110\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.6\"/><circle cx=\"200\" cy=\"86.0\" r=\"4\" fill=\"#c9a04a\"/><circle cx=\"230\" cy=\"98.0\" r=\"4\" fill=\"#c9a04a\"/><circle cx=\"260\" cy=\"110.0\" r=\"4\" fill=\"#c9a04a\"/><text x=\"230\" y=\"128\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">branch（試す場所）</text></svg>"}'),

  ('linux-q151', 'Gitとバージョン管理の基礎',
   '作業用の「ブランチ」を分けて作業することの利点として最も適切なものはどれか。',
   NULL::text,
   '["本流(main)を汚さずに、新しい変更を試したり作業したりできる", "ブランチを作ると、パソコンのディスク容量が自動的に2倍に増える", "ブランチを作ると、それまでのコミット履歴がすべて自動的に消去される", "ブランチを作ると、ネットワーク接続なしでは一切作業できなくなる"]',
   0, '[0]', 'single',
   '{"asked": "ブランチを分けて作業する利点を選ぶ問題。", "point": "ブランチの利点は「本流を汚さずに試せる」こと。", "kid": "コミットの積み重ねで学んだ通り、Gitの履歴は積み重なっていく。ブランチは、その積み重ねを「本流(main)」から分けて、別の線として枝分かれさせる仕組み。分けた枝の中で自由に試したり失敗したりしても、本流はそのまま影響を受けない。うまくいったら、後から本流に合流させることもできる。", "eg": "たとえるなら、料理のレシピを本番の1冊(本流)にいきなり書き込むのではなく、試作用のメモ(ブランチ)に書いて試してみるようなもの。うまくいったら本番のレシピに清書して合流させる。", "terms": [["ブランチ", "本流(main)から分かれた、別の作業の流れ。本流に影響を与えずに試せる"], ["main", "多くの場合、基準となる本流のブランチの名前"]], "why_asked": "「ブランチ」という言葉だけを覚えて、なぜ分ける必要があるのかという理由(本流を汚さない)が抜けている状態を防ぐ問題。", "think": "もし全員が本流(main)に直接、試行錯誤の変更を書き込んでいくと、まだ完成していない不安定な変更が本流に混ざり込み、他の人にも影響が及んでしまう。ブランチを分けることで、「まだ試している最中の変更」を本流から隔離しておき、本流はいつでも安定した状態を保てるようにする。試した変更がうまくいったと確認できてから、初めて本流に合流させる、という段階を踏めるのがブランチの利点である。", "vs": "「コミット」は履歴の1つの区切りであるのに対し、「ブランチ」は履歴の流れそのものを枝分かれさせる仕組み、という階層の違いを意識しておく。", "usecase": "新しいテストコードを試しに書いてみたいとき、本流を汚さずにブランチ上で試せるのは、QA・開発いずれの作業でも日常的に使われる考え方。", "opt": ["正解。本流(main)を汚さずに、新しい変更を試したり作業したりできる。", "ブランチを作ることと、ディスク容量が自動的に2倍に増えることは無関係であり、そのような仕組みはない。", "ブランチを作ることと、それまでのコミット履歴が消去されることは無関係であり、むしろ履歴は保持されたまま枝分かれする。", "ブランチの作成自体はネットワーク接続が無くても手元で行える操作であり、常時接続が必須というわけではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">コミットの積み重ね</text><line x1=\"40\" y1=\"70\" x2=\"300\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.6\"/><circle cx=\"60\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"110\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"160\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"300\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><text x=\"170\" y=\"90\" text-anchor=\"middle\" font-size=\"9\" fill=\"#60a5fa\">main（本流）</text><path d=\"M160,70 C 200,70 220,110 260,110\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.6\"/><circle cx=\"200\" cy=\"86.0\" r=\"4\" fill=\"#c9a04a\"/><circle cx=\"230\" cy=\"98.0\" r=\"4\" fill=\"#c9a04a\"/><circle cx=\"260\" cy=\"110.0\" r=\"4\" fill=\"#c9a04a\"/><text x=\"230\" y=\"128\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">branch（試す場所）</text></svg>"}'),

  ('linux-q152', 'Gitとバージョン管理の基礎',
   'Gitが、ネットワークのカテゴリではなくLinuxに関する図解ドリルの中で扱われている背景として最も適切なものはどれか。',
   NULL::text,
   '["Linuxカーネルの開発者であるLinus Torvaldsが、大人数での分散開発を管理する必要から作った経緯があるため", "GitはLinuxというOSのために専用に作られたツールであり、他のOSではまったく使うことができないものであるため", "Gitはネットワークの接続設定を細かく変更するためだけに作られた、専用のコマンドであるため", "GitはLinuxカーネルというプログラムそのものの一部分であり、切り離すことのできない機能であるため"]',
   0, '[0]', 'single',
   '{"asked": "GitがLinuxの文脈で語られる背景を選ぶ問題。", "point": "GitはLinuxカーネル開発の必要性から、Linus Torvaldsによって作られたという生い立ちを持つ。", "kid": "Linuxカーネル自体、世界中の大勢の開発者が関わる、とても大きなプロジェクト。誰が何を変更したかをきちんと管理する仕組みが必要になり、Linuxカーネルの生みの親であるLinus Torvaldsが、その必要性からGitを作った、という経緯がある。", "eg": "たとえるなら、大人数が同時に関わる大きな共同プロジェクトを進めるうちに、専用の「進行管理ノート」が必要になって作られた、というような生い立ち。", "terms": [["Linus Torvalds", "Linuxカーネルの生みの親であり、Gitの開発者でもある人物"]], "why_asked": "Gitを単なる「便利な道具」としてではなく、Linuxという世界とのつながりを含めて理解しているか、生い立ちのエピソードを通じて確認する問題。", "think": "Linuxカーネルの開発は、世界中の非常に多くの開発者が同時並行で関わる、大規模で分散した作業である。この規模の開発を管理するには、「誰が・いつ・何を変更したか」を正確に記録し、多数の変更を安全に統合できる仕組みが不可欠だった。既存のツールでは要件を満たせなかったことから、Linus TorvaldsがGitを新たに作り出した、という経緯がある。この生い立ちから、Gitが「分散型」であることや、大規模な共同作業に強い設計になっていることにもつながっている。", "vs": "「GitはLinux専用のツール」という誤解に注意。生まれた経緯はLinuxカーネル開発だが、現在ではOSを問わず、様々なソフトウェア開発の現場で広く使われている。", "usecase": "この生い立ちを知っておくと、「なぜGitは大人数での分散した共同作業に強いのか」という設計思想の理由が腹落ちしやすくなる。", "opt": ["正解。Linuxカーネルの開発者であるLinus Torvaldsが、大人数での分散開発を管理する必要から作った経緯があるため。", "GitはLinux以外のOS（WindowsやmacOSなど）でも広く使われており、Linux専用というわけではない。", "Gitはファイルの変更履歴を管理するための仕組みであり、ネットワークの設定変更を専門に行うコマンドではない。", "GitはLinuxカーネルとは別に開発・配布されている独立したソフトウェアであり、カーネルの一部そのものではない。"], "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"18\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"62\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">Linuxカーネル</text><text x=\"62\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">大規模開発</text><line x1=\"108\" y1=\"52\" x2=\"121\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"125\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">履歴管理が</text><text x=\"170\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">必要に</text><line x1=\"215\" y1=\"52\" x2=\"228\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"232\" y=\"35\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"278\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">Torvaldsが</text><text x=\"278\" y=\"61\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">Gitを開発</text></svg>"}'),

  ('linux-q153', 'Gitとバージョン管理の基礎',
   '「バックアップを取ること」と「バージョン管理(Gitなど)を使うこと」の違いとして最も適切なものはどれか。',
   NULL::text,
   '["バックアップは全体のコピーを残すことが中心、バージョン管理は変更の履歴・差分を追跡できることが中心", "バックアップとバージョン管理はまったく同じ目的・同じ仕組みであり、呼び方が違うだけである", "バックアップはネットワーク上でしか行えず、バージョン管理は手元のパソコンでしか行えない", "バックアップは無料でしかできず、バージョン管理は必ず有料である"]',
   0, '[0]', 'single',
   '{"asked": "バックアップとバージョン管理の違いを選ぶ問題。", "point": "バックアップは「まるごとコピー」中心、バージョン管理は「変化の履歴」中心という違い。", "kid": "バックアップは「今の状態をまるごとコピーして残しておく」ことが中心の考え方。バージョン管理は「何がどう変わったか」という変化そのものを記録し、いつでも過去の状態に戻ったり、変化を比較したりできることが中心の考え方。似ているようで、重視しているものが違う。", "eg": "たとえるなら、バックアップは「今日撮った写真をまるごと保存しておく」こと。バージョン管理は「昨日の写真と今日の写真を見比べて、どこがどう変わったかを記録しておく」こと。", "terms": [["バックアップ", "ある時点の状態をまるごとコピーして残しておくこと"], ["バージョン管理", "変更の履歴・差分を記録し、追跡・比較・差し戻しができるようにすること"]], "why_asked": "「Gitもバックアップの一種でしょ」という漠然とした理解のままだと、バージョン管理ならではの利点(差分を追える、特定の変更だけ取り消せる)が見えなくなる。", "think": "バックアップは「その瞬間の状態をまるごと保存する」ことに主眼があり、複数のバックアップを見比べて「どこがどう変わったか」を細かく追う用途にはあまり向いていない。一方バージョン管理は、変更のたびに「何が変わったか」という差分を記録していくため、「いつ・誰が・どの部分を変えたせいで問題が起きたか」を細かく追跡したり、特定の変更だけを選んで取り消したりすることができる。両者は「安全策を用意する」という点では似ているが、重視している情報の粒度が異なる。", "vs": "「まるごと保存(バックアップ)」と「変化を細かく記録(バージョン管理)」は、どちらも安心材料になるが、できることの粒度が違う点を区別しておく。", "usecase": "テストコードが壊れた原因を、直近の変更点だけをピンポイントで確認したいときは、まるごとのバックアップよりもバージョン管理の差分表示の方が役に立つ。", "opt": ["正解。バックアップは全体のコピーを残すことが中心、バージョン管理は変更の履歴・差分を追跡できることが中心という違いがある。", "両者は似た目的(安全に備える)を持つが、重視している情報(全体のコピーか、変化の履歴か)が異なり、単なる呼び方の違いではない。", "バックアップもバージョン管理も、ネットワーク上・手元のパソコンのどちらでも行うことができ、この説明のような排他的な制約はない。", "料金体系はサービスやツールによって様々であり、バックアップとバージョン管理を料金の有無だけで区別するのは正しくない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#60a5fa\">バックアップ</text><text x=\"250\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c9a04a\">バージョン管理</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"90\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">まるごとコピー</text><text x=\"90\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">その瞬間の保存</text><text x=\"250\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">変化の履歴</text><text x=\"250\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">差分を追跡</text></svg>"}'),

  ('linux-q154', 'Gitとバージョン管理の基礎',
   'ソフトウェア品質保証(QA)の実務にとって、バージョン管理の考え方を理解しておくことがどのように役立つか。',
   NULL::text,
   '["いつ・誰の変更からテストが失敗し始めたかを履歴からたどり、原因調査を効率化できる", "バージョン管理を理解すると、テストの実行速度そのものが自動的に速くなる", "バージョン管理を理解すると、テストケースの数が自動的に増える", "バージョン管理を理解すると、テスト対象のソフトウェアのバグが自動的に修正される"]',
   0, '[0]', 'single',
   '{"asked": "QA実務にとってバージョン管理の理解が役立つ理由を選ぶ問題。", "point": "バージョン管理の理解は、「いつ・誰の変更から壊れたか」を履歴からたどる力に直結する。", "kid": "テストが急に失敗し始めたとき、「最近の何かの変更が原因だろう」というところまでは想像がつく。バージョン管理の考え方(コミットの積み重ね、履歴を追う)を理解していれば、「どの時点のコミットから失敗し始めたか」を履歴からたどっていくことができ、原因調査がぐっと効率的になる。", "eg": "たとえるなら、体調を崩したときに「最近の生活で何か変わったこと」を振り返るようなもの。日々の記録(履歴)があれば、原因になった変化を特定しやすい。", "terms": [["原因調査", "問題が発生した理由を突き止めるための調査。バージョン管理の履歴が手がかりになる"]], "why_asked": "このドリル全体の読者像(QA6年、Web/AI開発を志望)に合わせて、Linuxの技術知識が実務にどうつながるかを最後に明示的に結びつける問題。", "think": "テストが失敗するようになった原因を探すとき、「最近、何が変わったか」を知ることは非常に重要な手がかりになる。バージョン管理の履歴には、変更のたびに「誰が・いつ・何を」変えたかが記録されているため、テストが通っていた最後のコミットと、失敗し始めた最初のコミットを比較すれば、疑わしい変更の範囲をぐっと絞り込める。これは、原因不明のまま闇雲に調査するよりもずっと効率的な、体系立った原因調査の手段になる。", "vs": "「テストコードを書く技術」と「変更履歴をたどって原因を絞り込む技術」は別の技術であり、後者がバージョン管理の理解によって支えられている、という関係を押さえておく。", "usecase": "自動テストが特定の日から不安定になったとき、その前後のコミット履歴を確認して怪しい変更を洗い出す、というのはQAの現場で実際によく行われる調査手順。", "opt": ["正解。いつ・誰の変更からテストが失敗し始めたかを履歴からたどり、原因調査を効率化できる。", "バージョン管理の理解そのものが、テストの実行速度を自動的に速くするような効果を持つわけではない。", "バージョン管理の理解そのものが、テストケースの数を自動的に増やすような効果を持つわけではない。", "バージョン管理の理解そのものが、テスト対象のソフトウェアのバグを自動的に修正するような効果を持つわけではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">コミットの積み重ね</text><line x1=\"40\" y1=\"70\" x2=\"300\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.6\"/><circle cx=\"60\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"110\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"160\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"300\" cy=\"70\" r=\"4\" fill=\"#60a5fa\"/><text x=\"170\" y=\"90\" text-anchor=\"middle\" font-size=\"9\" fill=\"#60a5fa\">main（本流）</text><path d=\"M160,70 C 200,70 220,110 260,110\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.6\"/><circle cx=\"200\" cy=\"86.0\" r=\"4\" fill=\"#c9a04a\"/><circle cx=\"230\" cy=\"98.0\" r=\"4\" fill=\"#c9a04a\"/><circle cx=\"260\" cy=\"110.0\" r=\"4\" fill=\"#c9a04a\"/><text x=\"230\" y=\"128\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">branch（試す場所）</text></svg>"}')
) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'linux-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
